const setup=(bm,request,value=0,index=0,length=0)=>Uint8Array.of(bm,request,value&255,value>>>8,index&255,index>>>8,length&255,length>>>8);
const little=(bytes,offset)=>new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength).getUint32(offset,true);
export class PicoUSBHost{
 constructor(usb){this.usb=usb;this.clear();usb.onUSBEnabled=()=>{this.clear();usb.resetDevice();};usb.onResetReceived=()=>{this.stage='address';usb.sendSetupPacket(setup(0,5,1));};usb.onEndpointWrite=(ep,data)=>this.receive(ep,data);usb.onEndpointRead=(ep,size)=>{this.pendingReads.set(ep,size);this.pump(ep);};}
 clear(){this.initialized=false;this.kind='none';this.stage='reset';this.descriptors=[];this.descriptorLength=0;this.inEndpoint=-1;this.outEndpoint=-1;this.pendingReads=new Map();this.queues=new Map();this.reports=[];this.packets=[];this.tag=0;this.control=null;this.msc=null;}
 record(direction,ep,data){this.packets.push({direction,endpoint:ep,length:data.length});if(this.packets.length>64)this.packets.shift();}
 send(ep,data){if(!this.queues.has(ep))this.queues.set(ep,[]);this.queues.get(ep).push(Uint8Array.from(data));this.pump(ep);}
 pump(ep){const q=this.queues.get(ep),size=this.pendingReads.get(ep);if(!q?.length||size===undefined)return;const bytes=q[0],part=bytes.slice(0,size);if(part.length===bytes.length)q.shift();else q[0]=bytes.slice(size);this.pendingReads.delete(ep);this.record('OUT',ep,part);this.usb.endpointReadDone(ep,part);}
 receive(ep,data){data=Uint8Array.from(data);this.record('IN',ep,data);if(ep===0){if(this.stage==='address'){this.stage='config-head';this.usb.sendSetupPacket(setup(0x80,6,0x200,0,9));}else if(this.stage==='config-head'){if(data.length!==9||data[1]!==2)return;this.descriptorLength=data[2]|data[3]<<8;if(this.descriptorLength>1024)throw Error('USB descriptor sınırı.');this.stage='config';this.usb.sendSetupPacket(setup(0x80,6,0x200,0,this.descriptorLength));}else if(this.stage==='config'){this.descriptors.push(...data);if(this.descriptors.length>=this.descriptorLength){this.parse();this.stage='configure';this.usb.sendSetupPacket(setup(0,9,1));}}else if(this.stage==='configure'){if(this.kind==='cdc'){this.stage='dtr';this.usb.sendSetupPacket(setup(0x21,0x22,3));}else this.ready();}else if(this.stage==='dtr')this.ready();else if(this.control&&!this.control.done){const t=this.control;if(t.inbound)t.data.push(...data);if(!t.inbound||t.data.length>=t.length||data.length<64){t.done=true;this.stage='idle';}}return;}
 if(ep!==this.inEndpoint)return;if(this.kind==='cdc')this.onSerialData?.(data);else if(this.kind==='hid'){this.reports.push(Array.from(data));if(this.reports.length>32)this.reports.shift();}else if(this.kind==='msc'&&this.msc&&!this.msc.done){const t=this.msc;if(data.length===13&&little(data,0)===0x53425355&&little(data,4)===t.tag){t.status=data[12];t.residue=little(data,8);t.done=true;}else{if(t.data.length+data.length>16384)throw Error('USB MSC veri sınırı.');t.data.push(...data);}}}
 ready(){this.initialized=true;this.stage='idle';this.onDeviceConnected?.();}
 parse(){let cls=0;for(let i=0;i<this.descriptors.length;){const d=this.descriptors,n=d[i],type=d[i+1];if(n<2||i+n>d.length)throw Error('USB descriptor geçersiz.');if(type===4){cls=d[i+5];if(cls===10)this.kind='cdc';else if(cls===3)this.kind='hid';else if(cls===8)this.kind='msc';else if(cls===0xfe&&d[i+6]===1)this.kind='dfu';}if(type===5&&(cls===10||cls===3||cls===8)){const address=d[i+2];if(address&128)this.inEndpoint=address&15;else this.outEndpoint=address&15;}i+=n;}if(this.kind==='none')throw Error('USB sınıfı desteklenmiyor.');}
 startControl({bm,request,value=0,index=0,length=0,data=[]}){if(!this.initialized||this.stage!=='idle'||this.control&&!this.control.done)throw Error('USB host hazır değil veya kontrol aktarımı sürüyor.');if(!Number.isInteger(length)||length<0||length>1024||!(bm&128)&&data.length!==length)throw Error('USB kontrol uzunluğu geçersiz.');this.control={request,length,inbound:!!(bm&128),data:[],done:false};this.stage='control';if(!(bm&128)&&length){this.queues.set(0,[Uint8Array.from(data)]);this.pump(0);}this.usb.sendSetupPacket(setup(bm,request,value,index,length));return this.control;}
 sendSerialByte(byte){if(this.kind==='cdc'&&this.initialized)this.send(this.outEndpoint,[byte]);}
 command({action,value=0,lba=0,block=0,text=''}){if(action==='hid-led'){if(this.kind!=='hid'||!Number.isInteger(value)||value<0||value>31)throw Error('HID LED değeri 0..31 olmalı.');return this.startControl({bm:0x21,request:9,value:0x200,length:1,data:[value]});}if(action.startsWith('msc-')){if(!Number.isInteger(lba)||lba<0||lba>65535)throw Error('LBA geçersiz.');if(action==='msc-inquiry')return this.startSCSI([0x12,0,0,0,36,0],{length:36});if(action==='msc-capacity')return this.startSCSI([0x25,0,0,0,0,0,0,0,0,0],{length:8});const cmd=[action==='msc-write'?0x2a:0x28,0,0,0,lba>>>8,lba&255,0,0,1,0];if(action==='msc-read')return this.startSCSI(cmd,{length:512});if(action==='msc-write')return this.startSCSI(cmd,{length:512,data:Array.from({length:512},(_,i)=>(i+0x84)&255)});}if(action.startsWith('dfu-')){if(this.kind!=='dfu'||!Number.isInteger(block)||block<0||block>65535)throw Error('DFU hedefi/blok geçersiz.');if(action==='dfu-status')return this.startControl({bm:0xa1,request:3,length:6});if(action==='dfu-upload')return this.startControl({bm:0xa1,request:2,value:block,length:16});if(action==='dfu-download'){const data=Array.from(new TextEncoder().encode(text));if(!data.length||data.length>256)throw Error('DFU verisi 1..256 bayt olmalı.');return this.startControl({bm:0x21,request:1,value:block,length:data.length,data});}const req={'dfu-manifest':1,'dfu-abort':6,'dfu-clear':4}[action];if(req!==undefined)return this.startControl({bm:0x21,request:req});}throw Error('USB host komutu geçersiz.');}
 startSCSI(command,{length=0,data=[]}={}){if(!this.initialized||this.kind!=='msc'||this.msc&&!this.msc.done)throw Error('MSC hazır değil.');if(command.length<1||command.length>16||!Number.isInteger(length)||length<0||length>16384||data.length&&data.length!==length)throw Error('MSC komutu geçersiz.');const write=data.length>0,tag=++this.tag,cbw=new Uint8Array(31),v=new DataView(cbw.buffer);v.setUint32(0,0x43425355,true);v.setUint32(4,tag,true);v.setUint32(8,length,true);cbw[12]=write?0:128;cbw[14]=command.length;cbw.set(command,15);this.msc={tag,data:[],status:null,residue:null,done:false};this.send(this.outEndpoint,cbw);if(write)for(let i=0;i<data.length;i+=64)this.send(this.outEndpoint,data.slice(i,i+64));return this.msc;}
 snapshot(){const preview=t=>t?{done:t.done,status:t.status??null,residue:t.residue??null,bytes:t.data.length,hex:t.data.slice(0,64).map(b=>b.toString(16).padStart(2,'0')).join(' ')}:null;return{connected:this.initialized,kind:this.kind,transport:'Virtual USB '+this.kind.toUpperCase(),reports:this.reports.slice(-8),msc:preview(this.msc),control:preview(this.control),packets:this.packets.slice(-16)};}
}
